int /* <=== exports_resolve_default */ 
exports_resolve_default (struct nbdkit_exports *exps, struct backend *b,
                         int readonly)
{
  const char *def = NULL;

  if (exps->use_default) {
    def = backend_default_export (b, readonly);
    exps->use_default = false;
  }
  if (def)
    return nbdkit_add_export (exps, def, NULL);
  return 0;
}

